"""Triton implementation of ``aten::_aminmax`` (reduce-all min/max pair).

Reference semantics (established by target probes, not assumption):
  * NaN poisons BOTH outputs; Triton's tl.minimum/tl.maximum/tl.min/tl.max suppress
    NaN on this backend even with propagate_nan=ALL, so a separate NaN flag is
    carried per program and folded in the epilogue.
  * +-inf are ordinary data values, so masked lanes use the dtype reduction
    identity (min: +inf / iinfo.max, max: -inf / iinfo.min), never a finite sentinel.
  * numel == 0 raises the same RuntimeError aten raises (aten has no identity for
    the reduce-all form).
  * 0-dim input returns two 0-dim tensors of the input dtype.
  * the logical index space, not storage order, defines the reduced set, so
    non-contiguous views take a per-dim strided path.

Launch shapes:
  * small contiguous n -> one kernel, grid (1,), stores both scalars.
  * large contiguous n -> partial kernel grid (G,) + finalize kernel (1,).
  * non-contiguous     -> strided kernel, grid (1,).

Accumulator dtypes (KIND):
  0 -> float32 AND bfloat16 input, float32 accumulator
  1 -> float16 input, accumulator kept in fp16 inside the streaming loop; the
       [BLOCK] accumulator is upcast to fp32 once before the cross-lane reduce
       (removes one per-element convert from the hot loop)
  2 -> int8/uint8/int16/int32, int32 accumulator
  3 -> int64, int64 accumulator

bfloat16 cannot use kind 1: on this backend tl.minimum promotes a bf16 operand to
fp32, so the loop-carried accumulator would change type (probe-verified: "Loop-carried
variable acc_min has initial type bf16 but is re-assigned to fp32"). fp16 min/max does
lower natively, so only fp16 gets the in-dtype accumulate.
"""

import torch
import triton
import triton.language as tl

_EMPTY_MSG = (
    "aminmax(): cannot compute aminmax over an empty dimension as the operation "
    "has no identity."
)

_KIND = {
    torch.float32: 0,
    torch.float16: 1,
    torch.bfloat16: 0,
    torch.int8: 2,
    torch.uint8: 2,
    torch.int16: 2,
    torch.int32: 2,
    torch.int64: 3,
}

_ONESHOT_MAX = 262144  # elements: below this a single launch wins
_CTA_PER_SM = 8
_CTA_PER_SM_LARGE = 16
_LARGE_N = 2097152  # above this many elements more programs pay for themselves
_SM_CACHE = [0]


def _num_sm():
    v = _SM_CACHE[0]
    if not v:
        try:
            v = int(
                torch.cuda.get_device_properties(
                    torch.cuda.current_device()
                ).multi_processor_count
            )
        except Exception:
            v = 8
        _SM_CACHE[0] = v
    return v


def _oneshot_block(n):
    b = 1024
    while b < n and b < 4096:
        b *= 2
    return b


@triton.jit
def _aminmax_oneshot(x_ptr, o_min, o_max, n, BLOCK: tl.constexpr, KIND: tl.constexpr):
    # MIN_ID is the neutral element of the min accumulator (+infinite / iinfo.max),
    # MAX_ID the neutral element of the max accumulator (-infinite / iinfo.min).
    if KIND == 0:
        ACC = tl.float32
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 1:
        ACC = x_ptr.dtype.element_ty
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 2:
        ACC = tl.int32
        MIN_ID = 2147483647
        MAX_ID = -2147483647 - 1
    else:
        ACC = tl.int64
        MIN_ID = 9223372036854775807
        MAX_ID = -9223372036854775807 - 1

    acc_min = tl.full([BLOCK], MIN_ID, ACC)
    acc_max = tl.full([BLOCK], MAX_ID, ACC)
    if KIND < 2:
        acc_nan = tl.zeros([BLOCK], tl.int32)

    full_iters = n // BLOCK
    for i in tl.range(0, full_iters):
        offs = i * BLOCK + tl.arange(0, BLOCK)
        x = tl.load(x_ptr + offs).to(ACC)
        acc_min = tl.minimum(acc_min, x)
        acc_max = tl.maximum(acc_max, x)
        if KIND < 2:
            acc_nan = acc_nan | (x != x).to(tl.int32)

    tail_tiles = tl.cdiv(n, BLOCK) - full_iters
    for j in tl.range(0, tail_tiles):
        offs = (full_iters + j) * BLOCK + tl.arange(0, BLOCK)
        # Clamp out-of-range lanes onto element 0 instead of substituting a neutral
        # value: element 0 is already part of the reduced set, so min/max are
        # unchanged and the load stays dtype-stable (a Python-float `other`/`where`
        # operand would promote an fp16 accumulator to fp32 and break the loop-carried
        # type).
        safe = tl.where(offs < n, offs, 0)
        x = tl.load(x_ptr + safe).to(ACC)
        acc_min = tl.minimum(acc_min, x)
        acc_max = tl.maximum(acc_max, x)
        if KIND < 2:
            acc_nan = acc_nan | (x != x).to(tl.int32)

    if KIND < 2:
        p_min = tl.min(acc_min.to(tl.float32))
        p_max = tl.max(acc_max.to(tl.float32))
        bad = tl.max(acc_nan) != 0
        p_min = tl.where(bad, float("nan"), p_min)
        p_max = tl.where(bad, float("nan"), p_max)
    else:
        p_min = tl.min(acc_min)
        p_max = tl.max(acc_max)
    tl.store(o_min, p_min.to(o_min.dtype.element_ty))
    tl.store(o_max, p_max.to(o_max.dtype.element_ty))


@triton.autotune(
    configs=[
        # BLOCK/num_warps pairs span 4-32 elements per thread: this backend budgets a
        # small vector register file (compiler pass reports vrf-budget=24) and three
        # [BLOCK] accumulators (min, max, nan-flag) already need
        # 3 * BLOCK/(32*num_warps) registers per thread, so the low-register end of the
        # range has to be measured on the real workloads.
        triton.Config({"BLOCK": 512}, num_warps=4),  # 4 elem/thread
        triton.Config({"BLOCK": 1024}, num_warps=4),  # 8
        triton.Config({"BLOCK": 1024}, num_warps=8),  # 4
        triton.Config({"BLOCK": 2048}, num_warps=4),  # 16
        triton.Config({"BLOCK": 2048}, num_warps=8),  # 8
        triton.Config({"BLOCK": 2048}, num_warps=16),  # 4
        triton.Config({"BLOCK": 4096}, num_warps=4),  # 32
        triton.Config({"BLOCK": 4096}, num_warps=8),  # 16
        triton.Config({"BLOCK": 8192}, num_warps=8),  # 32
    ],
    key=["bucket"],
)
@triton.jit
def _aminmax_partial(
    x_ptr,
    s_min,
    s_max,
    s_flag,
    n,
    G,
    bucket,
    BLOCK: tl.constexpr,
    KIND: tl.constexpr,
    I64: tl.constexpr,
):
    pid = tl.program_id(0)
    if KIND == 0:
        ACC = tl.float32
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 1:
        ACC = x_ptr.dtype.element_ty
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 2:
        ACC = tl.int32
        MIN_ID = 2147483647
        MAX_ID = -2147483647 - 1
    else:
        ACC = tl.int64
        MIN_ID = 9223372036854775807
        MAX_ID = -9223372036854775807 - 1

    acc_min = tl.full([BLOCK], MIN_ID, ACC)
    acc_max = tl.full([BLOCK], MAX_ID, ACC)
    if KIND < 2:
        acc_nan = tl.zeros([BLOCK], tl.int32)

    full_iters = (n // BLOCK) // G
    for i in tl.range(0, full_iters):
        if I64:
            base = (pid + i * G).to(tl.int64) * BLOCK
        else:
            base = (pid + i * G) * BLOCK
        offs = base + tl.arange(0, BLOCK)
        x = tl.load(x_ptr + offs).to(ACC)
        acc_min = tl.minimum(acc_min, x)
        acc_max = tl.maximum(acc_max, x)
        if KIND < 2:
            acc_nan = acc_nan | (x != x).to(tl.int32)

    tail_tiles = tl.cdiv(n, BLOCK) - full_iters * G
    tail_iters = tl.cdiv(tail_tiles, G)
    for j in tl.range(0, tail_iters):
        tidx = full_iters * G + pid + j * G
        if I64:
            base = tidx.to(tl.int64) * BLOCK
        else:
            base = tidx * BLOCK
        offs = base + tl.arange(0, BLOCK)
        safe = tl.where(offs < n, offs, 0)
        x = tl.load(x_ptr + safe).to(ACC)
        acc_min = tl.minimum(acc_min, x)
        acc_max = tl.maximum(acc_max, x)
        if KIND < 2:
            acc_nan = acc_nan | (x != x).to(tl.int32)

    if KIND < 2:
        p_min = tl.min(acc_min.to(tl.float32))
        p_max = tl.max(acc_max.to(tl.float32))
    else:
        p_min = tl.min(acc_min)
        p_max = tl.max(acc_max)
    tl.store(s_min + pid, p_min.to(s_min.dtype.element_ty))
    tl.store(s_max + pid, p_max.to(s_max.dtype.element_ty))
    if KIND < 2:
        tl.store(s_flag + pid, tl.max(acc_nan))


@triton.jit
def _aminmax_finalize(
    s_min,
    s_max,
    s_flag,
    o_min,
    o_max,
    G,
    BLOCK_R: tl.constexpr,
    KIND: tl.constexpr,
):
    idx = tl.arange(0, BLOCK_R)
    m = idx < G
    if KIND < 2:
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 2:
        MIN_ID = 2147483647
        MAX_ID = -2147483647 - 1
    else:
        MIN_ID = 9223372036854775807
        MAX_ID = -9223372036854775807 - 1

    if KIND < 2:
        v_min = tl.load(s_min + idx, mask=m, other=0).to(tl.float32)
        v_max = tl.load(s_max + idx, mask=m, other=0).to(tl.float32)
        r_min = tl.min(tl.where(m, v_min, MIN_ID))
        r_max = tl.max(tl.where(m, v_max, MAX_ID))
        fv = tl.load(s_flag + idx, mask=m, other=0)
        bad = tl.max(tl.where(m, fv, 0)) != 0
        r_min = tl.where(bad, float("nan"), r_min)
        r_max = tl.where(bad, float("nan"), r_max)
    else:
        v_min = tl.load(s_min + idx, mask=m, other=0)
        v_max = tl.load(s_max + idx, mask=m, other=0)
        r_min = tl.min(tl.where(m, v_min, MIN_ID))
        r_max = tl.max(tl.where(m, v_max, MAX_ID))
    tl.store(o_min, r_min.to(o_min.dtype.element_ty))
    tl.store(o_max, r_max.to(o_max.dtype.element_ty))


@triton.jit
def _aminmax_strided(
    x_ptr,
    o_min,
    o_max,
    n,
    a0,
    a1,
    a2,
    a3,
    a4,
    a5,
    a6,
    a7,
    b0,
    b1,
    b2,
    b3,
    b4,
    b5,
    b6,
    b7,
    BLOCK: tl.constexpr,
    KIND: tl.constexpr,
):
    if KIND == 0:
        ACC = tl.float32
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 1:
        ACC = x_ptr.dtype.element_ty
        MIN_ID = float("inf")
        MAX_ID = float("-inf")
    elif KIND == 2:
        ACC = tl.int32
        MIN_ID = 2147483647
        MAX_ID = -2147483647 - 1
    else:
        ACC = tl.int64
        MIN_ID = 9223372036854775807
        MAX_ID = -9223372036854775807 - 1

    acc_min = tl.full([BLOCK], MIN_ID, ACC)
    acc_max = tl.full([BLOCK], MAX_ID, ACC)
    if KIND < 2:
        acc_nan = tl.zeros([BLOCK], tl.int32)

    ntiles = tl.cdiv(n, BLOCK)
    for i in tl.range(0, ntiles):
        idx = i * BLOCK + tl.arange(0, BLOCK)
        r = tl.where(idx < n, idx, 0).to(tl.int64)
        off = tl.zeros([BLOCK], tl.int64)
        q = r % a7
        r = r // a7
        off = off + q * b7
        q = r % a6
        r = r // a6
        off = off + q * b6
        q = r % a5
        r = r // a5
        off = off + q * b5
        q = r % a4
        r = r // a4
        off = off + q * b4
        q = r % a3
        r = r // a3
        off = off + q * b3
        q = r % a2
        r = r // a2
        off = off + q * b2
        q = r % a1
        r = r // a1
        off = off + q * b1
        q = r % a0
        off = off + q * b0
        x = tl.load(x_ptr + off).to(ACC)
        acc_min = tl.minimum(acc_min, x)
        acc_max = tl.maximum(acc_max, x)
        if KIND < 2:
            acc_nan = acc_nan | (x != x).to(tl.int32)

    if KIND < 2:
        p_min = tl.min(acc_min.to(tl.float32))
        p_max = tl.max(acc_max.to(tl.float32))
        bad = tl.max(acc_nan) != 0
        p_min = tl.where(bad, float("nan"), p_min)
        p_max = tl.where(bad, float("nan"), p_max)
    else:
        p_min = tl.min(acc_min)
        p_max = tl.max(acc_max)
    tl.store(o_min, p_min.to(o_min.dtype.element_ty))
    tl.store(o_max, p_max.to(o_max.dtype.element_ty))


def _shape_stride(t):
    shape = t.shape
    stride = t.stride()
    shp = []
    std = []
    for d in range(len(shape)):
        s = shape[d]
        if s != 1:
            shp.append(s)
            std.append(stride[d])
    if not shp:
        shp = [1]
        std = [0]
    if len(shp) > 8:
        raise NotImplementedError(
            "_aminmax: non-contiguous input with more than 8 effective dims"
        )
    while len(shp) < 8:
        shp.append(1)
        std.append(0)
    return shp, std


def _aminmax(self):
    n = self.numel()
    if n == 0:
        raise RuntimeError(_EMPTY_MSG)
    dt = self.dtype
    kind = _KIND.get(dt, -1)
    if kind < 0:
        raise NotImplementedError("_aminmax: unsupported dtype %r" % (dt,))
    dev = self.device
    o_min = torch.empty((), dtype=dt, device=dev)
    o_max = torch.empty((), dtype=dt, device=dev)
    if self.is_contiguous():
        if n <= _ONESHOT_MAX:
            blk = _oneshot_block(n)
            _aminmax_oneshot[(1,)](
                self,
                o_min,
                o_max,
                n,
                BLOCK=blk,
                KIND=kind,
                num_warps=4 if blk <= 1024 else 8,
            )
        else:
            # Program count trades stream count against per-program fixed cost:
            # measured on this target, 8 programs per SM wins at ~1M elements (each
            # program then owns 8 grid-stride tiles) while 16 per SM wins at ~16.7M,
            # where every program still owns >= 32 tiles.
            per_sm = _CTA_PER_SM_LARGE if n > _LARGE_N else _CTA_PER_SM
            g = min(_num_sm() * per_sm, triton.cdiv(n, 1024))
            if g < 1:
                g = 1
            scr_min = torch.empty(g, dtype=dt, device=dev)
            scr_max = torch.empty(g, dtype=dt, device=dev)
            flags = torch.empty(g, dtype=torch.int32, device=dev) if kind < 2 else o_min
            _aminmax_partial[(g,)](
                self,
                scr_min,
                scr_max,
                flags,
                n,
                g,
                kind * 8 + (0 if n < 4194304 else 1),
                KIND=kind,
                I64=n > 2147483647,
            )
            _aminmax_finalize[(1,)](
                scr_min,
                scr_max,
                flags,
                o_min,
                o_max,
                g,
                BLOCK_R=triton.next_power_of_2(g),
                KIND=kind,
                num_warps=1,
            )
    else:
        shp, std = _shape_stride(self)
        _aminmax_strided[(1,)](
            self,
            o_min,
            o_max,
            n,
            shp[0],
            shp[1],
            shp[2],
            shp[3],
            shp[4],
            shp[5],
            shp[6],
            shp[7],
            std[0],
            std[1],
            std[2],
            std[3],
            std[4],
            std[5],
            std[6],
            std[7],
            BLOCK=1024,
            KIND=kind,
            num_warps=4,
        )
    return o_min, o_max
